use sublist::{Comparison, sublist as check_sublist};

#[test]
fn empty_lists() {
    let list_one: Array<u32> = array![];
    let list_two: Array<u32> = array![];
    let output = check_sublist(@list_one, @list_two);
    let expected = Comparison::Equal;
    assert_eq!(output, expected);
}

#[test]
#[ignore]
fn empty_list_within_non_empty_list() {
    let list_one: Array<u32> = array![];
    let list_two: Array<u32> = array![1, 2, 3];
    let output = check_sublist(@list_one, @list_two);
    let expected = Comparison::Sublist;
    assert_eq!(output, expected);
}

#[test]
#[ignore]
fn non_empty_list_contains_empty_list() {
    let list_one: Array<u32> = array![1, 2, 3];
    let list_two: Array<u32> = array![];
    let output = check_sublist(@list_one, @list_two);
    let expected = Comparison::Superlist;
    assert_eq!(output, expected);
}

#[test]
#[ignore]
fn list_equals_itself() {
    let list_one: Array<u32> = array![1, 2, 3];
    let list_two: Array<u32> = array![1, 2, 3];
    let output = check_sublist(@list_one, @list_two);
    let expected = Comparison::Equal;
    assert_eq!(output, expected);
}

